import re
import string


def q375(prediction, references):

    def normalize(s):
        s = s.lower().translate(str.maketrans("", "", string.punctuation))
        return " ".join(re.sub("\\b(a|an|the)\\b", " ", s).split())

    return int(
        any((normalize(prediction) == normalize(r) for r in references))
    )
